import tempfile
import unittest
from pathlib import Path

from helpers import ROOT, SHA, files_outside

from publish_topic import publish

EXPECTED_VALUES_LOCAL = (
    "# Generated by Jenkins (system-design/url-shortener). Never put secrets here.\n"
    f'revision: "{SHA}"\n'
    'imagePrefix: "reg/sd"\n'
    f'imageTag: "{SHA}"\n'
)


class PublishTopicTest(unittest.TestCase):
    def setUp(self):
        self._tmp = tempfile.TemporaryDirectory()
        self.gitops = Path(self._tmp.name)

    def tearDown(self):
        self._tmp.cleanup()

    def topic_dir(self) -> Path:
        return self.gitops / "topics" / "url-shortener"

    def test_publish_writes_only_topic_folder(self):
        changed = publish(self.gitops, ROOT, "url-shortener", "reg/sd", SHA)
        self.assertTrue(changed)
        self.assertTrue(all(p.startswith("topics/url-shortener/") for p in changed), changed)
        self.assertEqual(files_outside(self.gitops, "topics/url-shortener/"), [])

    def test_publish_copies_chart_values_and_metadata(self):
        publish(self.gitops, ROOT, "url-shortener", "reg/sd", SHA)
        chart = self.topic_dir() / "chart"
        self.assertTrue((chart / "Chart.yaml").is_file())
        self.assertTrue((chart / "templates" / "exclusivity.yaml").is_file())
        self.assertFalse((chart / "tests").exists())
        self.assertEqual((chart / "values-topic.yaml").read_text(),
                         (ROOT / "topics/url-shortener/deploy/values.yaml").read_text())
        self.assertEqual((self.topic_dir() / "topic.yaml").read_text(),
                         (ROOT / "topics/url-shortener/topic.yaml").read_text())

    def test_values_local_exact_content(self):
        publish(self.gitops, ROOT, "url-shortener", "reg/sd", SHA)
        self.assertEqual((self.topic_dir() / "values-local.yaml").read_text(), EXPECTED_VALUES_LOCAL)

    def test_publish_replaces_stale_chart_files(self):
        stale = self.topic_dir() / "chart" / "templates" / "old.yaml"
        stale.parent.mkdir(parents=True)
        stale.write_text("kind: Old\n")
        publish(self.gitops, ROOT, "url-shortener", "reg/sd", SHA)
        self.assertFalse(stale.exists())

    def test_publish_never_touches_active_yaml(self):
        active = self.gitops / "topics" / "active.yaml"
        active.parent.mkdir(parents=True)
        active.write_text("active: none\n")
        publish(self.gitops, ROOT, "url-shortener", "reg/sd", SHA)
        self.assertEqual(active.read_text(), "active: none\n")

    def test_publish_rejects_bad_topic_names(self):
        for bad in ("../charts", "URL_Shortener", "x", "missing-topic"):
            with self.assertRaises(ValueError):
                publish(self.gitops, ROOT, bad, "reg/sd", SHA)
        self.assertEqual(list(self.gitops.rglob("*.yaml")), [])

    def test_publish_rejects_short_revision(self):
        with self.assertRaises(ValueError):
            publish(self.gitops, ROOT, "url-shortener", "reg/sd", "abc123")

    def test_publish_rejects_bad_image_prefix(self):
        with self.assertRaises(ValueError):
            publish(self.gitops, ROOT, "url-shortener", "Reg Bad", SHA)


if __name__ == "__main__":
    unittest.main()
